const eco = document.createElement('div'); eco.id = 'eco'; eco.hidden = true;
eco.innerHTML = '<div id="ecoh"><span>Economy</span><button id="ecox">&times;</button></div><div id="ecot"></div><div id="ecob"></div>'; document.body.append(eco);
const ecoCell = t => e(t).replace(/\{(PC|RS|MS|BZ)\}/g, '<sup class="tg">$1</sup>').replace(/\u25c6/g, '<span class="hp" title="GM house price">&#9670;</span>');
function ecoRender() {
    const q = ($('#ecof') ? $('#ecof').value : '').toLowerCase();
    $('#ecot').innerHTML = ECO.map((s, i) => `<button data-et="${i}" class="${i == ecoTab ? 'on' : ''}">${e(s.n)}</button>`).join('');
    const s = ECO[ecoTab];
    $('#ecob').innerHTML = `<h3>${e(s.n)} <span class="mu">${e(s.sub)}</span></h3><input id="ecof" type="text" placeholder="Filter this tab..." value="${e(q)}"><table class="qt eco"><tr>${s.cols.map(c => `<th>${e(c)}</th>`).join('')}</tr>${s.rows.map(r => r.s ? (q ? '' : `<tr class="sub"><td colspan="${s.cols.length}">${e(r.s)}</td></tr>`) : (!q || r.join(' ').toLowerCase().includes(q) ? `<tr>${r.map(c => `<td>${ecoCell(c)}</td>`).join('')}</tr>` : '')).join('')}</table>${s.note ? `<p class="mu">${ecoCell(s.note)}</p>` : ''}`;
    const f = $('#ecof'); if (q && f) { f.focus(); f.setSelectionRange(q.length, q.length) }
}
$('#ecot').onclick = ev => { const b = ev.target.closest('[data-et]'); if (b) { ecoTab = +b.dataset.et; ecoRender() } };
eco.addEventListener('input', ev => { if (ev.target.id == 'ecof') ecoRender() });
$('#ecox').onclick = () => eco.hidden = true;
const ecoh = $('#ecoh'); let ed = null;
ecoh.onpointerdown = ev => { if (ev.target.id == 'ecox') return; const b = eco.getBoundingClientRect(); ed = { x: ev.clientX - b.left, y: ev.clientY - b.top }; ecoh.setPointerCapture(ev.pointerId) };
ecoh.onpointermove = ev => { if (!ed) return; eco.style.left = Math.max(0, Math.min(innerWidth - 80, ev.clientX - ed.x)) + 'px'; eco.style.top = Math.max(0, Math.min(innerHeight - 40, ev.clientY - ed.y)) + 'px' };
ecoh.onpointerup = () => ed = null;
[eco, rf].forEach(b => b.addEventListener('pointerdown', () => { zt++; b.style.zIndex = zt }));
const CAR = { "how": { "rows": [["1 · Choose the table", "Choose the table that fits how the PC spends their time in town. Different PCs may use different tables."], ["2 · Pay the event cost", "Each participant pays the full cost for the tier chosen (Core costs, pg. 92)."], ["3 · Roll 1d8 + the event's bonus", "Gain the XP and the result. Gold lost or won is a % of total gold left after paying."], ["Allies & tokens", "Go on the character sheet. Tokens are one use. An ally can be lost if abused or betrayed."], ["Treasure Tables 1 · 2 · 3 ◆", "Roll on the Core treasure table for levels 0-3 · 4-6 · 7-9."], ["Playing it out", "If the group plays out one PC's roll, everyone carousing is usually present (Core)."]], "note": "Costs & bonuses: Shadowdark Core Rules, pg. 92 · Event names flavored per table · ◆ GM house ruling. Shadowdark RPG © The Arcane Library · Custom Carousing Compendium." }, "tables": [{ "n": "1", "name": "The Traditional Revelry", "sub": "CHAOTIC TAVERN NIGHTS & DRUNKEN MISCHIEF", "events": [["30 gp", "+0", "A worthy night of drinking and festivity"], ["100 gp", "+1", "A day and night of revelry and gambling"], ["300 gp", "+2", "Two days crawling dozens of taverns"], ["600 gp", "+3", "Three-day voyage of fine food, drink & dice"], ["900 gp", "+4", "A hazy, weeklong bender"], ["1,200 gp", "+5", "A ten-day fete that takes over a district"], ["1,800 gp", "+6", "Two legendary weeks; the streets run red with wine"]], "outcomes": [["3 or less", "1 XP", "You blacked out and woke up in a horse stall. Lose 15% of your total gold. You have an enormous headache and a strange tattoo of a turnip on your arm."], ["4-6", "2 XP", "You gambled heavily with a local card-sharp. Lose 30% of your total gold. You did manage to keep a fancy silver flask (0 slots, worth 10 gp)."], ["7-9", "3 XP", "You started a massive bar brawl that wrecked the tavern. Lose 20% of your total gold in structural damages, but you made a **Rowdy Ally** who will jump into local fights with you."], ["10-12", "4 XP", "You successfully drank an entire dwarven mining platoon under the table. You gain a strong reputation. The local barkeeps will give you free standard drinks for life."], ["13", "5 XP", "You woke up wearing a stranger's ceremonial velvet robe. Lose 10% of your total gold. The robe takes up 1 slot but gives you a +1 bonus to Charisma checks with cultists."], ["14+", "6 XP", "You woke up in the local magistrate's personal bed. He thinks you are a visiting foreign noble. Roll on **Treasure Table 2** for a fancy signet ring or pocket watch you 'borrowed'."]] }, { "n": "2", "name": "Community & Charity Reverie", "sub": "ALTRUISTIC · LIFTING THE DESOLATE", "events": [["30 gp", "+0", "Hot meals for a street of beggars"], ["100 gp", "+1", "Repairing a widow's roof and the town well"], ["300 gp", "+2", "A week of soup kitchen and shelter"], ["600 gp", "+3", "Paying the debts of a dozen families"], ["900 gp", "+4", "Endowing the orphanage or infirmary"], ["1,200 gp", "+5", "A harvest festival for the whole town"], ["1,800 gp", "+6", "Rebuilding a burned-out quarter"]], "outcomes": [["3 or less", "1 XP", "You spent your coin trying to fix a broken water well, but a corrupt tax collector pocketed it. Lose 15% of your total gold. Local laborers respect your effort and offer free basic shelter."], ["4-6", "2 XP", "You funded a week-long soup kitchen and shelter for town refugees. Lose 30% of your total gold. The experience humbles you; gain a temporary +1 to your next Charisma check with commoners."], ["7-9", "3 XP", "You completely paid off outstanding debts or medical fees for several struggling families. Gain a **Working-Class Ally** (blacksmith or farmer) who gives you a 50% discount on standard services."], ["10-12", "4 XP", "You donated heavily to the local orphanage or infirmary. The town considers you a local hero. Gain a **Token of Gratitude**; cash it in to automatically pass a single social check with local guards."], ["13", "5 XP", "You sponsored a grand public harvest festival, keeping the town safe and festive. The positive energy restores your spirit; gain +1 maximum hit points as a morale boost for your next adventure."], ["14+", "6 XP", "An elderly artisan, deeply moved by your immense charity, gifts you a sacred family heirloom. Roll on **Treasure Table 2** to see what masterwork or historical item they handed down to you."]] }, { "n": "3", "name": "The Sacred Vigil & Devotion", "sub": "LAWFUL · CLEANSING THE SOUL", "events": [["30 gp", "+0", "A night's vigil and candle offerings"], ["100 gp", "+1", "Alms, fasting and a day of prayer"], ["300 gp", "+2", "Restoring a defaced wayside shrine"], ["600 gp", "+3", "Pilgrimage to a holy site and back"], ["900 gp", "+4", "Commissioning relics and illuminated texts"], ["1,200 gp", "+5", "A new bell and altar for the chapel"], ["1,800 gp", "+6", "Endowing a temple and its holy order"]], "outcomes": [["3 or less", "1 XP", "You spent your time fasting in isolation, but a stray altar candle spark burned your pouch. Lose 10% of your total gold. You leave with a peaceful mind but smelling strongly of smoke."], ["4-6", "2 XP", "You paid to restore a defaced religious shrine or historical monument. Lose 25% of your total gold. Your meticulous work acts as meditation; gain a +1 bonus to your next Wisdom saving throw."], ["7-9", "3 XP", "You helped temple scribes translate and preserve deteriorating ancient ethical treatises. Gain a **Temple Ally** (acolyte or librarian) who will gladly research historical or monster lore for free."], ["10-12", "4 XP", "You stood a grueling 48-hour silent guard vigil over a sacred tomb to protect it from graverobbers. Your discipline hardens; gain advantage on your next saving throw against fear or paralysis."], ["13", "5 XP", "You successfully mediated a long-standing, bitter feud between two rival factions without bloodshed. The high priest blesses you with a **Holy Scroll of Protection** (tier 1 priest spell scroll)."], ["14+", "6 XP", "Your absolute righteousness draws the attention of a higher power. They entrust you with a sacred artifact to fight the dark. Gain a random **Magic Item** with a minor holy or lawful property."]] }, { "n": "4", "name": "Civic Duty & Town Defense", "sub": "LAWFUL / NEUTRAL · RULE OF LAW", "events": [["30 gp", "+0", "Lanterns and a round for the night watch"], ["100 gp", "+1", "Patching the town wall and gate"], ["300 gp", "+2", "Arming a neighborhood watch"], ["600 gp", "+3", "A week drilling the militia"], ["900 gp", "+4", "Spears and shields for the militia"], ["1,200 gp", "+5", "A town-wide defense drill and feast"], ["1,800 gp", "+6", "Rebuilding a watchtower and garrison"]], "outcomes": [["3 or less", "1 XP", "You volunteered to patch rotten timbers on the town defensive walls. Your coin pouch fell into a muddy trench. Lose 15% of your total gold. Your muscles are incredibly sore, but the wall is sturdier."], ["4-6", "2 XP", "You organized a neighborhood watch to protect shopkeepers from burglaries. Lose 20% of your total gold buying lanterns. Merchants are grateful and buy your next treasure for 10% more."], ["7-9", "3 XP", "You spent days drilling the local ragtag militia in shield-wall tactics. Gain a **Militia Ally** (the Watch Captain) who will look the other way for a minor civil infraction or provide muscle."], ["10-12", "4 XP", "You tracked down and peacefully negotiated the return of stolen livestock, resolving conflict through law. The magistrate rewards your civic mind with a Bounty Reward. Roll on **Treasure Table 1**."], ["13", "5 XP", "You spent downtime offering free, rigorous self-defense training to town laborers and peasants. Sharpening your own fundamentals improves your form; gain +1 to your next initiative roll."], ["14+", "6 XP", "You organized a highly successful town-wide defensive drill that deterred a group of bandit scouts. The governor officially honors you and awards you a **Masterwork Weapon or Armor** piece from the armory. ◆"]] }, { "n": "5", "name": "Occult Research & Mystery", "sub": "NEUTRAL · FORBIDDEN LORE", "events": [["30 gp", "+0", "Buying a drunk scholar's rumors"], ["100 gp", "+1", "Archive fees and candles for a day"], ["300 gp", "+2", "Forbidden pamphlets and old maps"], ["600 gp", "+3", "A hired sage for a week of study"], ["900 gp", "+4", "A rare tome from the black market"], ["1,200 gp", "+5", "A séance with a famed medium"], ["1,800 gp", "+6", "An expedition to a sealed library"]], "outcomes": [["3 or less", "1 XP", "You spent your coin buying maps from a shady hooded scholar; they turned out to be fake doodles. Lose 15% of your total gold. You have ink stains on your fingers that won't wash off for a week."], ["4-6", "2 XP", "You locked yourself in a dusty archive searching for a lost dungeon entrance. Lose 25% of your total gold in library fees. You find a clue: gain a +2 bonus to Intelligence checks on your next crawl."], ["7-9", "3 XP", "You investigated a strange series of local disappearances and found an eerie calling card. Gain an **Occult Ally** (a local investigator) who can identify strange runes or occult cult symbols for you."], ["10-12", "4 XP", "You solved a legendary tavern riddle box that hadn't been opened in decades. Inside you find a map showing a hidden cache. Gain a **secret location** on your map with guaranteed extra loot."], ["13", "5 XP", "You deciphered a fragment of a forbidden pre-human text before your nose started bleeding. You learn a dark truth. Gain a **tier 1 wizard spell scroll**, but take −1 to your next Wisdom save."], ["14+", "6 XP", "You uncovered a conspiracy linking a local merchant guild to a cosmic entity. You pocketed a strange talisman from their secret meeting room. Gain a random strange, alien **Magic Item**."]] }, { "n": "6", "name": "Gambling & the High-Stakes Underground", "sub": "CHAOTIC", "events": [["30 gp", "+0", "A night at the knucklebone tables"], ["100 gp", "+1", "A seat at a backroom card game"], ["300 gp", "+2", "Two nights in the fighting-pit stands"], ["600 gp", "+3", "High-stakes dice with a guildmaster"], ["900 gp", "+4", "A week inside the underground den"], ["1,200 gp", "+5", "Buying into the Thieves' Guild game"], ["1,800 gp", "+6", "Bankrolling a pit-fighting tournament"]], "outcomes": [["3 or less", "1 XP", "You got completely cleaned out by a group of card-playing goblins. Lose 50% of your total gold. You also had to surrender your favorite boots to pay off your final bar tab."], ["4-6", "2 XP", "You played a tight, cautious game of knucklebones all night. Lose 10% of your total gold. You walked away with a **lucky rabbit's foot**: reroll a single natural 1 on an attack (one use)."], ["7-9", "3 XP", "You won big against an aggressive thug, but had to fight your way out of the alley afterwards. Gain 15% more gold than you started with, but a local criminal gang is looking for payback."], ["10-12", "4 XP", "You completely outsmarted a wealthy guildmaster in a high-stakes dice match. Gain 40% more gold than you started with and a **Guild Invitation** granting entry to private merchant clubs."], ["13", "5 XP", "You bet on an absurd underdog in the underground fighting pits and won against all odds. Gain 60% more gold than you started with and a reputation as a reckless, fearless gambler."], ["14+", "6 XP", "You won the deed to a mysterious, abandoned property outside of town from a panicked nobleman. Gain 20% more gold and the **Deed to a Ruined Tower or Warehouse** (a future base)."]] }, { "n": "7", "name": "Aristocratic Galas & Intrigue", "sub": "SOCIAL CLIMBING · COURTLY FAVORS", "events": [["30 gp", "+0", "Fine clothes and a borrowed invitation"], ["100 gp", "+1", "A seat at a lesser noble's supper"], ["300 gp", "+2", "Hosting a private salon"], ["600 gp", "+3", "A three-day hunt with the gentry"], ["900 gp", "+4", "A masquerade ball in your honor"], ["1,200 gp", "+5", "Sponsoring a tourney for the court"], ["1,800 gp", "+6", "A royal gala the whole city talks about"]], "outcomes": [["3 or less", "1 XP", "You committed a horrific social faux pas by insulting a duchess's outfit. Lose 20% of your total gold in steep courtly fines; you are permanently barred from entering the High District."], ["4-6", "2 XP", "You were tricked into investing in an incredibly terrible local theatrical play. Lose 40% of your total gold. On the bright side, you keep a fancy, silk-lined velvet cloak (0 slots)."], ["7-9", "3 XP", "You spent the evening trading polite barbs with cutthroat politicians. Gain a **Noble Ally** who can secure you a private audience with the Magistrate, but a rival house now plots against you."], ["10-12", "4 XP", "You won a dramatic high-society duel of wits or fine archery against an arrogant lordling. Gain a **Royal Favor** token; cash it in to completely erase a single minor crime or arrest."], ["13", "5 XP", "You stumbled into a secret, forbidden romance with the ruler's closest relative. They gift you a fine silver signet ring worth 100 gp, but warn you to leave the city before sunrise."], ["14+", "6 XP", "You wake up in the royal guest palace. The King believes you saved his life from an invisible assassin and grants you a royal charter. Roll on **Treasure Table 3** for a pristine masterwork piece of gear. ◆"]] }, { "n": "8", "name": "Wilderness Expeditions & Scouting", "sub": "NEUTRAL · SURVIVAL", "events": [["30 gp", "+0", "A day hunting in the near woods"], ["100 gp", "+1", "A hired guide for an overnight trek"], ["300 gp", "+2", "Two days mapping the fringe trails"], ["600 gp", "+3", "A week tracking beasts in the hills"], ["900 gp", "+4", "Outfitting a mountain survey"], ["1,200 gp", "+5", "A ten-day expedition with porters"], ["1,800 gp", "+6", "A two-week march across the wilds"]], "outcomes": [["3 or less", "1 XP", "You got hopelessly lost in the nearby bramble-woods trying to map a shortcut. Lose 10% of your total gold in ruined gear. You are covered in itchy briar scratches for your next journey."], ["4-6", "2 XP", "You tracked a rare, majestic beast through the mountains but lost its trail. Lose 20% of your total gold in supply costs. Your instincts sharpen; gain +1 to your next navigation check."], ["7-9", "3 XP", "You cleared a dangerous infestation of giant spiders from an important logging trail. Gain a **Wilderness Ally** (a local ranger or woodcutter) who will guide your party through the local woods for free."], ["10-12", "4 XP", "You discovered an ancient hunter's cache hidden inside a hollowed-out ironwood tree. Gain a perfectly balanced **Masterwork Shortbow or Hunting Knife** (0 slots)."], ["13", "5 XP", "You befriended a grumpy, reclusive druid by helping nurse an injured dire wolf back to health. The druid rewards you with a rare **Herbal Poultice** that acts as a Potion of Healing when applied."], ["14+", "6 XP", "You mapped a safe, hidden trail through a notoriously treacherous mountain pass. Local merchant caravans pay you handsomely for the map. Gain a Bounty Reward: roll on **Treasure Table 2**."]] }] }; let carTab = 0;
const car = document.createElement('div'); car.id = 'car'; car.hidden = true; car.style.left = '170px'; car.style.top = '95px';
car.innerHTML = '<div id="carh"><span>Carousing</span><button id="carx">&times;</button></div><div id="cart"></div><div id="carb"></div>'; document.body.append(car);
const carTxt = t => e(t).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\u25c6/g, '<span class="hp" title="GM house ruling">&#9670;</span>');
function carRender() {
    const T = ['How It Works', ...CAR.tables.map(t => t.n + ' ' + t.name)];
    $('#cart').innerHTML = T.map((n, i) => `<button data-ct="${i}" class="${i == carTab ? 'on' : ''}">${e(n)}</button>`).join('');
    const t = CAR.tables[carTab - 1];
    $('#carb').innerHTML = carTab == 0 ? `<h3>How It Works</h3><table class="qt eco">${CAR.how.rows.map(r => `<tr><td>${carTxt(r[0])}</td><td>${carTxt(r[1])}</td></tr>`).join('')}</table><p class="mu">${carTxt(CAR.how.note)}</p>` :
        `<h3>${e(t.n + ' ' + t.name)} <span class="mu">${e(t.sub)}</span></h3><table class="qt cr"><tr><th>Cost</th><th>Bonus</th><th>The Event (each participant pays)</th></tr>${t.events.map(r => `<tr><td>${e(r[0])}</td><td>${e(r[1])}</td><td>${carTxt(r[2])}</td></tr>`).join('')}</table><table class="qt cr"><tr><th>1d8 + Bonus</th><th>XP</th><th>Outcome &amp; Consequences</th></tr>${t.outcomes.map(r => `<tr><td>${e(r[0])}</td><td class="xp">${e(r[1])}</td><td>${carTxt(r[2])}</td></tr>`).join('')}</table><p class="mu">&#9670; = GM house ruling. Costs &amp; bonuses: Shadowdark Core Rules, pg. 92.</p>`
}
$('#cart').onclick = ev => { const b = ev.target.closest('[data-ct]'); if (b) { carTab = +b.dataset.ct; carRender() } };
$('#carx').onclick = () => car.hidden = true;
const carh = $('#carh'); let cd = null;
carh.onpointerdown = ev => { if (ev.target.id == 'carx') return; const b = car.getBoundingClientRect(); cd = { x: ev.clientX - b.left, y: ev.clientY - b.top }; carh.setPointerCapture(ev.pointerId) };
carh.onpointermove = ev => { if (!cd) return; car.style.left = Math.max(0, Math.min(innerWidth - 80, ev.clientX - cd.x)) + 'px'; car.style.top = Math.max(0, Math.min(innerHeight - 40, ev.clientY - cd.y)) + 'px' };
carh.onpointerup = () => cd = null;
car.addEventListener('pointerdown', () => { zt++; car.style.zIndex = zt });
const HK = [{ "n": 1, "ring": "A", "type": "Quest", "src": "Trial Gate", "reg": "Frostholm", "title": "The Missing Five", "hear": "\"Nine went down at dusk and four came up. Their kin are at the gate every hour, and the captain is tired of saying the Trial takes what it takes.\" The captain will pay a black-cloak's wage to learn whether the other five are dead or only lost.", "truth": "Under the keep, 0 hexes. A flooded side branch of the Trial holds the five alive and sleeping in a cistern, kept fresh by a Primordial Slime (level 6) that treats them as a larder.", "reward": "10 gp per survivor, the captain's quiet thanks, and a clear look at what the Trial is really for." }, { "n": 2, "ring": "A", "type": "Quest", "src": "Warden's Hall", "reg": "Frostholm", "title": "The Gutted Toll-house", "hear": "\"Lamplight in the old toll-house after dark, and that place was smashed hollow in some raid nobody wrote down.\" The Warden wants it checked before it becomes a bandit nest.", "truth": "2012, 1 hex out. A Hunt deserter named Pell hides here with a stolen set of Hunt trail maps, and a Frostbite goblin watcher is paid in scraps to look away. Pell will trade the maps for a pardon.", "reward": "40 gp from the Warden, or Pell's maps (accurate out to 8 hexes) and an oath: the Warden will pardon one crime you have committed." }, { "n": 3, "ring": "A", "type": "Quest", "src": "The Crucible", "reg": "Frostholm", "title": "Paper Bounties", "hear": "\"Somebody keeps nailing fake bounties to the signpost on the west road. Easy marks, good money, and every crew that rides out to collect comes back a man short.\" The proprietor wants the forger found.", "truth": "The signpost is 1912 (2 hexes). A Hunt debt-broker forges the notices. The named targets wait in the hollow at 1909 (3 hexes), where Obsidian Court scouts pay him silver for every living body.", "reward": "30 gp, free ale at the Crucible for a month, and the broker's ledger, which names a vampire's coin." }, { "n": 4, "ring": "A", "type": "Quest", "src": "Temple of the Last Hearth", "reg": "Frostholm", "title": "Black Stones", "hear": "\"Hunters leave a black stone on the cairn for each friend they could not carry home. This week the stones were stacked into a name overnight, and the temple buried that man a year ago.\" A priest asks for someone steady.", "truth": "2010, 2 hexes. A murdered Hunt veteran, now a wight, wants his true name carved so he can rest. His body lies in a cleft behind the cairn, killed for his stipend by a comrade still in Frostholm.", "reward": "20 gp and the blessing Divine Halo (hostile spells that target you are DC 15 to cast), granted by the priests." }, { "n": 5, "ring": "A", "type": "Quest", "src": "Beacon Inn", "reg": "Frostholm", "title": "The Beacon Goes Dark", "hear": "\"That beacon has burned eleven years. Twice this month it was out by dawn, and there is a shape at the treeline with a rack of antlers for a head. It doesn't move. It watches.\" The innkeeper pays for a night's watch.", "truth": "1812, 3 hexes. A Rune-Elk scout in an antler mask is testing the Hunt's border, snuffing the beacon to see who answers. The elves want a parley, not a fight.", "reward": "A season of free beds. A good parley earns an oath: the elves will guide you unharmed through the Emerald Wood." }, { "n": 6, "ring": "A", "type": "Quest", "src": "The Broken Spur", "reg": "Frostholm", "title": "Biscuit Is Not a Warhorse", "hear": "\"My best mule bolted west with a saddlebag that was not mine. A scout's savings are in it. Bring Biscuit back and I will forget the bag ever existed.\" The stablemaster fears the scout more than the wilds.", "truth": "1913, 3 hexes. Biscuit has joined a herd of hippogriff and will not be led off, because the beasts like her. The bag holds 55 gp and a letter naming a Hunt officer who takes bribes.", "reward": "50 gp of stable credit, the letter, and a lever on that officer." }, { "n": 7, "ring": "A", "type": "Quest", "src": "The Broken Spur", "reg": "Emerald Wood", "title": "Who Bleeds the Elk?", "hear": "\"Two elk drained in a week at the thicket. The elves blame us. I say something is feeding that can't stand light.\" A rune-elk tamer offers coin to find the culprit before the elves find a Hunt crew to hang.", "truth": "The trail runs from 1913 (3 hexes) northwest toward the elk range at 1310 (8 hexes). The feeder is a vampire spawn in service to the Obsidian Court manor under 1806 (7 hexes).", "reward": "60 gp and an elf's thanks. The Court will know your faces." }, { "n": 8, "ring": "A", "type": "Quest", "src": "Warden's Hall", "reg": "Winter's Edge", "title": "The Patrol That Did Not Return", "hear": "\"Six cloaks rode south-west into the grass and never came home. A raven brought back a scrap of their cloth and a white feather that belongs to nothing of ours.\" The Warden offers 15 gp for every one alive.", "truth": "Frostbite goblins took them to the vents beneath 1916 (6 hexes), where the Pale Sphinx's riddlers question them. Two still live. The Sphinx wants a trade.", "reward": "15 gp per survivor, Hunt standing, and an audience on the Sphinx's terms." }, { "n": 9, "ring": "A", "type": "Quest", "src": "The Black Cellars", "reg": "Rimewastes", "title": "The Goblin in Vault Nine", "hear": "\"There is a goblin in vault nine shaking so hard the lantern chimes. Says its name is Nub and it ran from a town of bone where giants roll dice to see who gets eaten.\" The cellar-keeper wants it gone or explained.", "truth": "Nub is a Runt-Grown goblin who escaped the Shatter-Tooth ogres of the Dice Field (0802, 16 hexes northwest). Nine more will run if someone opens a path.", "reward": "Nub's rough map of the Rimewastes, 100 gp from the Warden for ogre intelligence, and nine grateful goblins." }, { "n": 10, "ring": "A", "type": "Mystery", "src": "The Iron Ward", "reg": "Rotbark", "title": "The Sword with Red Clay", "hear": "\"A veteran brought this in to be re-edged. It is wet with red clay and something sweet. He died on my floor saying the river was alive. The clay will not wash off.\" The smith wants to know where it came from.", "truth": "The clay is from the Heartblood River in Rotbark (0004, 21 hexes west). The veteran fled the Cult of the Leech. Others may follow him.", "reward": "A masterwork re-edge on any weapon, 30 gp, and the knowledge that something far west is bleeding the river." }, { "n": 11, "ring": "A", "type": "Quest", "src": "Climber's Rest", "reg": "Emerald Wood", "title": "Amber by the Handful", "hear": "\"A guide called Ysolt says the trees in the northeast weep amber by the handful and the beads glow brighter every year. The Warden wants a sack tested.\" Ysolt needs two partners.", "truth": "The Resin Wood, 1809 (4 hexes). The glow is a ward the elves grow. Taking a sack angers them and draws the Court. Ysolt hides that she once led a crew into a vampire hollow.", "reward": "A share of the sale (about 200 gp) and Ysolt's map of the Resin Wood." }, { "n": 12, "ring": "A", "type": "Quest", "src": "The Ravenry", "reg": "Winter's Edge", "title": "Kites on the Wind", "hear": "\"Four birds this month came back without their messages and one with a net-burn across the wing. Somebody is catching ravens.\" The Ravenry keeper wants them found.", "truth": "A rock stack at 2015 (4 hexes) whistles in the wind. Frostbite goblins fly net-kites from it and read the Hunt's mail for the Pale Sphinx.", "reward": "30 gp, and the stolen messages, which show the Sphinx knows the Warden's patrol schedule." }, { "n": 13, "ring": "B", "type": "Quest", "src": "The Broken Spur", "reg": "Golden Waves", "title": "The Smiling Scarecrows", "hear": "\"Herders swear the scarecrows in the wheat are in a different field every dawn. Painted smiles, every one. A boy counted forty and then stopped counting.\" Nobody will cross that field at dusk.", "truth": "1713 (4 hexes). The scarecrows are animated by the ghost of a farmer who wants his daughter's grave found beneath the collapsed windmill at 1612 (5 hexes). Lay him to rest and they stand still.", "reward": "A lockbox of 80 gp under the windmill floor, and a very relieved herder." }, { "n": 14, "ring": "B", "type": "Quest", "src": "Warden's Hall", "reg": "Emerald Wood", "title": "The Burned Sawmill", "hear": "\"The Hunt cut timber west of the pass until the camp burned. Elves, say the clerks. There is a ring of oaks there tied together with living vines that tighten every year.\" The Warden wants the camp reopened, quietly.", "truth": "1709 (4 hexes). The oak ring is an elven boundary shrine. A crew felled one and the elves burned the camp. A sincere apology and a replanted oak would win cutting rights.", "reward": "50 gp, lumber rights, and elven goodwill." }, { "n": 15, "ring": "B", "type": "Mystery", "src": "Climber's Rest", "reg": "Frostholm", "title": "Tally Marks", "hear": "\"Somebody keeps scribbling tally marks on the walls of the burned farm. Some say it counts the dead and some say it counts days.\" Guides argue over it for free drinks.", "truth": "1914 (4 hexes). The tallies are a scout code pointing to a cache of 200 gp and supplies one hex away. The scout's partner was sold out at the hollow at 1909.", "reward": "The cache, plus the name of the traitor." }, { "n": 16, "ring": "B", "type": "Quest", "src": "Blackcloak Outfitters", "reg": "Emerald Wood", "title": "Silk Worth Its Weight", "hear": "\"There is a ravine full of spiders big as ponies to the west, and their silk spins a cloak that keeps you warm in a blizzard.\" The Outfitters pays 25 gp for each cloak's worth.", "truth": "1609 (5 hexes). Giant spiders and an ettercap. The ettercap has cocooned a living Hunt scout who has been there nine days.", "reward": "25 gp per cloak's worth and 50 gp from the scout's crew." }, { "n": 17, "ring": "B", "type": "Quest", "src": "Temple of the Last Hearth", "reg": "Emerald Wood", "title": "The Mirror Pool", "hear": "\"Brother Aldous lost his wife this winter. He means to drink from a pool of black water ringed with white toadstools. They say it shows you your dead.\" He begs an escort.", "truth": "1610 (5 hexes). The water is a hallucinogen the Forgotten Folk use to speak to ancestors. The visions are convincing, and the hanged ghost of a lost scout lurks at the edge.", "reward": "The temple's free healing for as long as you live, and a hard conversation." }, { "n": 18, "ring": "B", "type": "Quest", "src": "Climber's Rest", "reg": "Golden Waves", "title": "The Spiral Wheat", "hear": "\"Somebody lays the wheat flat in a spiral every night, one ring tighter each time. The herders say when it closes, the hill opens.\" Someone must stop it.", "truth": "1412 (7 hexes), on the way to the Spiral Hill (1512, 6 hexes). The dead beneath the hill lay the spiral. The standing stone at 1614 (5 hexes), scored with the same pattern, is its eye.", "reward": "A Kytherian Cog (300 gp) waits inside the mound, if you reach it before the spiral closes." }, { "n": 19, "ring": "B", "type": "Rumour", "src": "The Beacon Inn", "reg": "Golden Waves", "title": "The Door at the Top", "hear": "\"A hill in the wheat with a path that winds up in a spiral. At the top, a dark doorway. Nobody who goes in is seen again.\" Everyone has a cousin who almost went.", "truth": "1512 (6 hexes). A burial mound dungeon crowned with standing stones. Its dead are bound to an old order and do not leave. A second, hidden door is on the north slope.", "reward": "Treasure from the 7-9 table, and the order's seal." }, { "n": 20, "ring": "B", "type": "Quest", "src": "Warden's Hall", "reg": "Golden Waves", "title": "Eyes That Follow", "hear": "\"There are stones in the long grass with open eyes carved into them. A scout swore they watched him all the way to the next hill.\" The Warden's scribe wants rubbings.", "truth": "The Seven Eyes Citadel ruins, 1414 (7 hexes), and a half-buried watchtower with a sealed door at 1415 (7 hexes). The eyes are sentinels of a vanished order. The sealed door holds its last records.", "reward": "100 gp for a clean rubbing of the eye-stones, and a scholar's gratitude." }, { "n": 21, "ring": "B", "type": "Quest", "src": "The Crucible", "reg": "Emerald Wood", "title": "Honey and Wasps", "hear": "\"Wasp honey cures fever. The temple needs three jars and nobody will fetch it from the high branch where the nest hangs humming.\" The proprietor offers free drinks.", "truth": "1907 (5 hexes). A giant wasp nest. The honey does cure fever. A Rune-Elk beekeeper has been tending the nest and will bargain, if you do not burn it.", "reward": "30 gp from the temple, and the honey's secret from the elf." }, { "n": 22, "ring": "B", "type": "Rumour", "src": "The Beacon Inn", "reg": "Emerald Wood", "title": "The Tooth in the Forest", "hear": "\"A white stump in the wood glows like a tooth, ringed with elk skulls. When it glows bright, they say, something is near that does not belong.\" Scouts steer around it on principle.", "truth": "2007 (5 hexes). A ward-stump grown by the elves around the grave of the first rune-elk. It flares when vampires are close. The Hunt could use it.", "reward": "A Hunt bounty of 40 gp for mapping its flare radius." }, { "n": 23, "ring": "B", "type": "Quest", "src": "Temple of the Last Hearth", "reg": "Emerald Wood", "title": "The Burial Mound of the Elves", "hear": "\"The elves are asking Frostholm for help against the Court. Odd, since they used to shoot us on sight. A burial mound of theirs is being dug at night.\" The priest wants someone to check before the elves blame Frostholm.", "truth": "1509 (6 hexes). The mound is old, its runes fading. Vampire thralls are digging for an elven relic that could unseal the Court's cellar. The Rune-Elk will pay for it to be re-warded.", "reward": "80 gp from the elves, and an elf's oath of safe passage." }, { "n": 24, "ring": "B", "type": "Rumour", "src": "The Crucible", "reg": "Emerald Wood", "title": "The Manor That Isn't There", "hear": "\"A fog basin with no birds. They say there is a manor underneath, with perfume in the halls and servants who never blink. Go in and you come out gracious and very pale.\"", "truth": "1806 (7 hexes). The Obsidian Court's underground manor and estate, ruled by Lord Malakar. Invitations are real and are sent to the best fighters. Those who go return as thralls.", "reward": "Safe passage and 100 gp, at a price the invitation does not mention." }, { "n": 25, "ring": "B", "type": "Quest", "src": "The Broken Spur", "reg": "Emerald Wood", "title": "The Cave That Smells of Musk", "hear": "\"A cave west of the sawmill with claw marks round the mouth, higher than a man can reach. A bear, they say. A big one.\" The stablemaster has lost three pack goats.", "truth": "1806 (7 hexes). An owlbear dens in a cave mouth near the vampire's fog basin. Its claw marks are higher than a man's reach because it stands in a niche.", "reward": "40 gp from the stablemaster and the owlbear's pelt." }, { "n": 26, "ring": "B", "type": "Quest", "src": "Warden's Hall", "reg": "Emerald Wood", "title": "The Cut Bridge", "hear": "\"The hunters' rope bridge over the gully west of the thicket was cut last week, cut clean, not frayed. Somebody does not want us crossing.\" The Warden suspects the elves.", "truth": "1411 (7 hexes). A vampire thrall cut it to keep the Hunt from reaching the elven tree-city at 1408 (7 hexes), where an alliance is being discussed.", "reward": "60 gp and a secret: proof of the crimes of a revered knight of St. Terragnis who is secretly taking the Court's coin." }, { "n": 27, "ring": "B", "type": "Quest", "src": "The Warden's Hall", "reg": "Emerald Wood", "title": "A Letter for the Tree-City", "hear": "\"The Warden wants a letter delivered to the elves, and nobody has volunteered. They say the city hangs in the canopy with lanterns and music, and archers on every branch.\"", "truth": "1408 (7 hexes). The Rune-Elk's tree-city, with rune-elk stables among the trunks below. The elves will receive a messenger who comes unarmed. The Warden's letter proposes a treaty against the Court.", "reward": "A Hunt writ of free passage, 100 gp, and the elves' respect." }, { "n": 28, "ring": "B", "type": "Quest", "src": "The Broken Spur", "reg": "Emerald Wood", "title": "The Rune-Elk Calf", "hear": "\"A noble in the east wants a rune-elk calf. Alive. The tamers say you can only ride one if you give it a name. The elves say you can't ride one at all.\"", "truth": "1310 (8 hexes) is the elk range. Take a calf and the elves will track you for weeks. The calf can be traded for if you earn the herdmaster's trust.", "reward": "200 gp from the noble, or Gede's Blessing (speak to and understand animals) from the herdmaster." }, { "n": 29, "ring": "B", "type": "Quest", "src": "Temple of the Last Hearth", "reg": "Winter's Edge", "title": "The Sailors' Graveyard", "hear": "\"The temple keeps a wall of names for the lost. South-west there is a graveyard of sailors whose markers lean in the snow. Nobody knows who they are.\" The priests want their names.", "truth": "2017 (6 hexes). A graveyard of frozen sailors from the wrecks. The markers have names, and the dead call them out at dusk. The Frostbite goblins avoid it.", "reward": "A true blessing: Ghostwalk once per day, and the sailors' stolen coin (60 gp)." }, { "n": 30, "ring": "B", "type": "Quest", "src": "Climber's Rest", "reg": "Winter's Edge", "title": "The Troll in the Sea Cave", "hear": "\"A cave with riddle runes round the mouth, south-west past the frozen cliffs. A starving troll lives inside and answers riddles, they say, before eating.\" The Iron Ward wants troll hide.", "truth": "1816 (6 hexes). An ice troll, a prisoner of the Pale Sphinx's riddlers, chained to answer riddles. Free it and it follows you out. Kill it and the goblins hunt you.", "reward": "40 gp from the Iron Ward, or a troll bodyguard." }, { "n": 31, "ring": "B", "type": "Quest", "src": "Warden's Hall", "reg": "Winter's Edge", "title": "The Whistle Network", "hear": "\"The goblins talk in whistles, and there are cracks in the ridge that carry them for miles. A whole town under there, they say. The Warden wants it mapped.\"", "truth": "1916 (6 hexes) and 1817 (7 hexes). Two Frostbite goblin settlements beneath the ridge, linked by tunnels. The Sphinx rules them by fear. Their whistles are a code the Hunt can learn.", "reward": "100 gp for a map, and a bargain the goblins would rather make than another raid." }, { "n": 32, "ring": "B", "type": "Rumour", "src": "The Crucible", "reg": "Winter's Edge", "title": "The Ships on the Ice", "hear": "\"A cliff where the land just stops and below it a dozen wrecked ships ground on the ice, masts snapped like twigs. A pirate crew is still frozen in the pack with their gold.\"", "truth": "2018 (7 hexes). The wrecks of the Grinding Ice. The pirates of the Crimson Sky are among them, dead and preserved, with their treasure. A broken lighthouse watches the cliff.", "reward": "Treasure from the 4-6 table per wreck, and a map to the Crimson Sky's hold." }, { "n": 33, "ring": "B", "type": "Rumour", "src": "The Beacon Inn", "reg": "Winter's Edge", "title": "The Lighthouse That Lights Itself", "hear": "\"A ruined lighthouse in the snow with its lamp long dead. On moonless nights they say it lights anyway, and drowned sailors walk toward it.\"", "truth": "1616 (7 hexes). The door is iced shut. Something inside lights the lamp, a sailor's ghost that thinks the pack ice is still the sea.", "reward": "A drowned captain's seal worth 80 gp, and a ship's bell that rings for lost things." }, { "n": 34, "ring": "B", "type": "Quest", "src": "The Iron Ward", "reg": "Winter's Edge", "title": "The Black Sea Wall", "hear": "\"A wall of black stone half-buried in snow drifts, south-west of the vents. The smith says the stone is not from here. It rings like nothing he has ever hit.\"", "truth": "1716 (7 hexes). A broken sea-wall of black meteoric stone, hammered into a cliff by hands long dead. The Iron Ward wants a sample, and the stone is the same as the meteor at the Windfall Scar (1305).", "reward": "60 gp, and an oath: a dwarven forgemaster will make you a spectacular sword from the stone." }, { "n": 35, "ring": "B", "type": "Quest", "src": "Climber's Rest", "reg": "Winter's Edge", "title": "Riddles on the Rime Stair", "hear": "\"A tall tower on the ridge. Pale Sphinx scouts challenge everyone who passes with a riddle. A wrong answer, they say, and you forget your own name for a week.\"", "truth": "1717 (8 hexes). Pale Sphinx scouts keep the stair. Right answers earn passage and information. Wrong ones cost a memory. The Sphinx's reliquary lies above.", "reward": "A Sphinx's secret: the secret location of a rival adventuring party, and a spellscroll." }, { "n": 36, "ring": "B", "type": "Quest", "src": "Blackcloak Outfitters", "reg": "Blightcreep", "title": "Bread for the Mushroom Folk", "hear": "\"A drowned wood to the south-west where little capped folk tend toadstool gardens. Friendly, if you bring bread. They trade rare fungi for it, fresh loaves only.\" The Outfitters sells loaves at double.", "truth": "1315 (8 hexes). The mushroomfolk of the Drowned Wood. Their fungi cure poisons and fevers. They are afraid of the druids at 1015 (11 hexes), who are taking their gardens.", "reward": "Rare fungi worth 80 gp, and the mushroomfolk's alliance against the Rotting Leaf." }, { "n": 37, "ring": "B", "type": "Quest", "src": "The Crucible", "reg": "Golden Waves", "title": "The Rat King of the Silo", "hear": "\"A toppled grain silo in the wheat with rats nesting inside. They have learned a word. They say it over and over. The word is fed.\" A teamster offers coin.", "truth": "1513 (6 hexes). Dire rats and a wererat who calls itself their king. It speaks, and it bargains: leave it grain and it keeps the road clear.", "reward": "25 gp from the teamster, or the rat king's favour." }, { "n": 38, "ring": "B", "type": "Rumour", "src": "The Beacon Inn", "reg": "Golden Waves", "title": "The Sealed Watchtower", "hear": "\"A watchtower half-buried in the wheat with its door sealed. A cartographer swears the seal bears the Hunt's own mark, older than the Hunt.\"", "truth": "1415 (7 hexes). The tower belongs to the order of the Seven Eyes. The door opens to blood or to a spoken name found on the eye-stones at 1414.", "reward": "Treasure from the 7-9 table and a shocking truth about the Hunt's origins." }, { "n": 39, "ring": "B", "type": "Rumour", "src": "The Crucible", "reg": "Frostholm", "title": "The Wandering Merchant", "hear": "\"A merchant on a heavily laden camel in the snow, selling potions. He sold a man a map to his own grave, they say, and the map was right.\"", "truth": "No fixed hex. The Wandering Merchant appears anywhere in the Wilds, always when someone needs something and never when you look for him. He sells fair. Do not ask how he got here.", "reward": "A potion or scroll at fair price, and a warning from a very odd stranger." }, { "n": 40, "ring": "B", "type": "Quest", "src": "The Crucible", "reg": "Emerald Wood", "title": "The Deed to a Ruined Tower", "hear": "\"A Hunt gambler won a deed in a card game, a ruined tower out in the grass, and wants it gone. Cursed, he says. Nobody asks what the curse is.\" He will sell it for a round of drinks.", "truth": "1906 (6 hexes). A toppled watchtower with vines through its windows and a snapped banner pole. The previous owner was an Obsidian Court thrall, and the cellar holds his strongbox and a ledger of the Court's forward posts.", "reward": "The deed itself (a future base), 60 gp from the strongbox, and the ledger." }, { "n": 41, "ring": "C", "type": "Quest", "src": "Climber's Rest", "reg": "Rimewastes", "title": "The Mammoth Road", "hear": "\"The herds came south a month early this year, and the old hands say the ogres are walking behind them. A teamster counted forty tusks on the ridge at dawn.\" Nobody wants to be the first to look.", "truth": "1402 (13 hexes northwest). A waking frost dragon has driven the mammoth herds south, and the Shatter-Tooth ogres follow them toward Frostholm's approaches. The Warden needs a scout to learn how many ogres, and whether the herd can be turned.", "reward": "100 gp for an honest count, 200 gp more if the herd is turned from the pass, and the Warden's gratitude." }, { "n": 42, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Rimewastes", "title": "Six Men in the Whale", "hear": "\"Six armoured men chant around a fire inside the ribs of a drowned god, far in the north. Their prayers sound like ice breaking.\" A hunter went white telling it.", "truth": "0002 (21 hexes). Six orcs of the Blood of Ramlaat tend a fire beside an albino kraken locked in glassy ice, which they believe is their god asleep. It twitches when they bleed for it.", "reward": "The kraken's eye (a 150 gp gem) if the orcs are driven off, or Rite of Rage (once per day, deal double damage) if you win their trust." }, { "n": 43, "ring": "C", "type": "Rumour", "src": "The Ravenry", "reg": "Rimewastes", "title": "The Choir Under the Ice", "hear": "\"A crevasse in the far north sings, they say, and glows a different colour every night. Anyone who listens too long steps in.\" The keeper has heard it from three half-frozen couriers.", "truth": "0202 (19 hexes). A void spawn (level 7) fell into the crevasse and cannot climb out. Its song is a plea that rewires the listener. It will grant a gift to whoever frees it, then try to follow.", "reward": "The blessing Arcane Eye (three times per day, advantage to cast a spell), and a friend you cannot shake." }, { "n": 44, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Rimewastes", "title": "The City Under the Ice", "hear": "\"A pale city of elf stone lies half-buried in blue ice in the northwest. When the sun goes down, the shapes frozen in the walls move.\" A drunk veteran swears one of them waved.", "truth": "0502 (17 hexes). Ancient elven ruins entombed in a glacier. The shapes are frozen elves, and one is alive: a sentinel with a warning for the Rune-Elk about what lies beneath the Court's cellar.", "reward": "An elven relic worth 200 gp, the warning itself, and the Rune-Elk's thanks." }, { "n": 45, "ring": "C", "type": "Rumour", "src": "The Beacon Inn", "reg": "Rimewastes", "title": "Lanterns on the Ice", "hear": "\"There is a street of ice up north with warm springs beneath it, and a procession of little lights walks it every midnight. The ice groans like a ship.\" Travellers follow the lights home, the story goes, and are not seen again.", "truth": "1102 (14 hexes). Will-o'-wisps of ice drift over hot springs under a thin sheet. They lead travellers onto the thinnest ice. The springs themselves are a safe, warm haven for anyone who survives the walk.", "reward": "A glow-glass bauble worth 40 gp, and a warm shelter in a long winter." }, { "n": 46, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Rimewastes", "title": "The Sleeping Glacier", "hear": "\"A glacier creaks like a giant turning in its sleep, with blue chasms and a draft that smells of hot metal. Hunters go quiet when they pass it.\" A teamster crosses himself, then pretends he did not.", "truth": "1402 (13 hexes). A frost dragon sleeps behind an icy waterfall. The draft is her breath. Her hoard includes the Staff of Ord, which the Temple would pay dearly to see.", "reward": "A dragon's hoard from the 10+ treasure table, and very little time." }, { "n": 47, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Rimewastes", "title": "The Bear That Is a Hill", "hear": "\"A ridge shaped like a sleeping bear, with caves along its flanks breathing warm air. The ground sounds hollow. A trapper said he could hear it snore.\"", "truth": "1802 (11 hexes). A volcanic vent warms the ridge. Mammoths winter in the caves, and a polar bear with cubs guards the deepest one. The snoring is the vent.", "reward": "A mammoth tusk worth 120 gp, and a mother bear's fury if you take it." }, { "n": 48, "ring": "C", "type": "Rumour", "src": "The Beacon Inn", "reg": "Rimewastes", "title": "The Waste Walker", "hear": "\"A man in rime armour walks the northern snow with a sword of ice. He does not eat or sleep. He only asks if you have seen his king.\" Three people have told it with three different kings.", "truth": "The far north. The Waste Walker, a wight (level 10) bound to a lost frost-king's oath. He can be bargained with if given true news of the king's fate, and he will not break his word.", "reward": "His icy greatsword, and a dead king's blessing." }, { "n": 49, "ring": "C", "type": "Bounty", "src": "The Crucible", "reg": "Rimewastes", "title": "Hermit Leedrin's Last Hunt", "hear": "\"A hermit called Leedrin picks crews for his prey, one at a time, and lets them run first. They say he wears the boots of everyone he has caught.\" The Warden keeps a standing bounty.", "truth": "The northern snow, 14 or more hexes. A reaver (level 6) who hunts for sport. He will choose the party next. His cabin holds twenty pairs of boots and a stolen Hunt ledger.", "reward": "200 gp from the Warden and the contents of his cabin." }, { "n": 50, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Rimewastes", "title": "The Lumberjack", "hear": "\"A giant in a bearskin drags a log sled across the snow with a greataxe the size of a door. He is polite, they say, until you touch his logs.\" A teamster once offered him ale and was hauled home on the sled.", "truth": "The northern snow. The Lumberjack, a neutral ogre (level 6), loves logs and cannot bear being cheated. He trades pelts for ale and knows where the mammoth herds go.", "reward": "Pelts, a polite ogre, and a tip about the herds." }, { "n": 51, "ring": "C", "type": "Quest", "src": "The Crucible", "reg": "Rimewastes", "title": "The Ice Rat Tribe", "hear": "\"A tribe of goblins in the north sets traps in the snow and trades what it catches. They are not like the ogres' runts. They are free, and proud of it.\" A trader came back one boot short and smiling.", "truth": "The north, 15 or more hexes. The Ice Rat Tribe, free goblins who trade furs for iron and oil. Their traps are deadly but marked, if you know the signs.", "reward": "Furs, a goblin guide, and a northern gem worth 80 gp." }, { "n": 52, "ring": "C", "type": "Quest", "src": "The Crucible", "reg": "Rimewastes", "title": "The Ogre Wedding", "hear": "\"I'm told the giants in the bone town are having a wedding, and every guest has to bring a gift. Mammoth hides, mostly. A goblin runt said the food is the guests.\" Everyone laughs. A few do not.", "truth": "0802 (16 hexes northwest). The Shatter-Tooth ogres at the Dice Field really are holding a bride-price feast. Guests are honoured by custom. The party could enter the shanty town under truce, and meet the goblin slaves who want out.", "reward": "A trade pass to the ogre hunters, the freedom of a dozen goblin runts, and a great story." }, { "n": 53, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Brightscale Basin", "title": "The Village That Floats", "hear": "\"A village of reed huts and lashed rafts drifts on a great lake, with rope bridges between. The folk are scaled, and they trade fish for iron.\" A tamer swears they bite.", "truth": "0806 (13 hexes). The lizardfolk's floating village, bound to the lake and afraid of the sahuagin. They pay in fish, pearls and passage across the water for iron arrowheads and weapons.", "reward": "A pearl worth 40 gp, a boat across the lake, and a lizardfolk's gratitude." }, { "n": 54, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Brightscale Basin", "title": "The Whirlpool That Breathes", "hear": "\"A whirlpool turns slowly in the middle of the lake, and something pale glides just under the waves. They say the water drains once a decade.\" A fisherman's boy says it has a heartbeat.", "truth": "0610 (15 hexes). The sahuagin megadungeon at the bottom of the Bottomless Eye. The drain is a sealed gate. The pale thing is a sahuagin priestess surfacing to watch.", "reward": "Merfolk's Kiss (you can breathe water as though it were air), or the sahuagin's hoard." }, { "n": 55, "ring": "C", "type": "Quest", "src": "The Iron Ward", "reg": "Brightscale Basin", "title": "The Flower Sea", "hear": "\"A shore of beautiful flowers with thorns as long as knives, and water beyond with a red cast. Even the insects keep away.\" A herbalist wants a sample but will not go herself.", "truth": "0605 (15 hexes). The red tinge is the Heartblood River's taint drifting down from Rotbark. The flowers are poisonous, and a few can be distilled into a cure.", "reward": "60 gp and an antidote for the Heartblood's taint." }, { "n": 56, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Brightscale Basin", "title": "The Toll Ghost", "hear": "\"A bridge over white rapids with its arch cracked and two guard towers, doors swinging open. An old man in the left tower asks for a toll.\" The coin is real, they say, but nobody dares spend it.", "truth": "0808 (13 hexes). A dwarf-built bridge. The old man is the ghost of its last toll-keeper, who pays travellers out of a strongbox if they hear his story.", "reward": "80 gp from the strongbox and a dead dwarf's key." }, { "n": 57, "ring": "C", "type": "Quest", "src": "Climber's Rest", "reg": "Brightscale Basin", "title": "The Driftwood Hermit", "hear": "\"A hut of driftwood and scales on the river bank, with a thin green finned hermit who waves at everyone. He sells maps of the lake.\" A guide would not say what he trades for.", "truth": "0811 (13 hexes). A merfolk hermit exiled by the sahuagin. He knows a way into the megadungeon under the whirlpool, and he wants someone to take a message to a daughter still inside.", "reward": "A map of the Bottomless Eye and a merfolk's favour." }, { "n": 58, "ring": "C", "type": "Quest", "src": "Warden's Hall", "reg": "Golden Waves", "title": "The Last Camp in the Grass", "hear": "\"The Hunt keeps a camp far out in the long grass. No raven has come from it in a month, and the Warden has stopped talking about it.\" A clerk quietly asked a crew to look.", "truth": "1113 (10 hexes). The Green Throat, the Hunt's westernmost camp. The hunters have gone native, taken in by a Forgotten Folk community, and do not wish to return. The camp's stores hold 200 gp.", "reward": "Hunt standing, the stored gold if you take it quietly, and a hard decision about whether to bring them home." }, { "n": 59, "ring": "C", "type": "Rumour", "src": "The Beacon Inn", "reg": "Emerald Wood", "title": "The Gardeners in the Dark", "hear": "\"Glowing mushrooms sway in a dell far to the west, and somebody plants them in careful rows. The planting marks are fresh.\" A scout watched for an hour and saw no one.", "truth": "1109 (10 hexes). Glowcap Dell, tended by a Forgotten Folk gardener who sells rare fungi to the elves and fears the Court.", "reward": "Rare fungi worth 80 gp, and a secret about the elves' ward-stones." }, { "n": 60, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Emerald Wood", "title": "The Black Stone That Hums", "hear": "\"A pitted black stone the size of a barn sits in a crater, humming. Hair stands on end, and the air shimmers like a door not quite shut.\" A trapper lost his dog there.", "truth": "1305 (10 hexes). The Windfall Scar. A half-open crack in the world left a meteor of black stone. The same stone forms the sea-wall at 1716 (7 hexes). It rings when struck, and is the best metal in the Wilds.", "reward": "Meteoric iron worth 150 gp, and an oath: a dwarven forgemaster will make you a spectacular sword." }, { "n": 61, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Brightscale Basin", "title": "The Giants and the Horses", "hear": "\"Two hill giants walk the plains, each with a horse under one arm, and a cave yawns between the roots of a huge tree. They are always hungry.\" A horse-trader has not been the same since.", "truth": "0512 (16 hexes). The Lone Titan. The giants steal horses for a feast, and the cave is their larder, full of looted gear.", "reward": "100 gp in looted gear, and the surviving horses." }, { "n": 62, "ring": "C", "type": "Quest", "src": "The Iron Ward", "reg": "Brightscale Basin", "title": "The Cloven Boulder", "hear": "\"A boulder split in two with a tunnel between, and three stout figures cursing as they wedge beams against a wall. They are mining something they will not name.\" The smith's cousin swears it shines.", "truth": "0514 (16 hexes). A Dwarf Lord's miners are digging a mithral vein while duergar from Deephome try to steal it. The wall they brace is already failing.", "reward": "Mithral worth 120 gp and a forgemaster's oath of a spectacular sword." }, { "n": 63, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Brightscale Basin", "title": "Marga and the Crystals", "hear": "\"An old woman wanders the river banks gathering curative crystals and healing plants. She will heal anyone who asks, they say, as long as they do not ask twice.\"", "truth": "The river banks, 13 to 16 hexes. Marga the Wise is a travelling herbalist hunted by hags who want her recipes. She asks for an escort and will pay in cures.", "reward": "A healing draught worth 150 gp and a hag's curse lifted." }, { "n": 64, "ring": "C", "type": "Quest", "src": "The Crucible", "reg": "Blightcreep", "title": "The Cathedral of Moss", "hear": "\"A hut bigger than a church sits on a rise in the swamp, moss-grown, thatched with reeds and bones. The smoke smells of boiling herbs and something worse.\" A hunter says the garden in front is the loveliest thing he ever saw.", "truth": "0916 (12 hexes). The Black-Spit Hag Coven. They bargain with desperate travellers, and every bargain has a hook. Their garden grows the ingredients, and they hold the Obsidian Witchknife.", "reward": "A hag's boon at a price the hag will name later." }, { "n": 65, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Blightcreep", "title": "The Black Sap Grove", "hear": "\"Trees weeping black sap, antlers and skulls in the branches, and figures in green-tinged robes tending the swamp in silence.\" The sap burns like nothing else, a teamster says.", "truth": "1015 (11 hexes). The Circle of the Rotting Leaf, druids who believe they are saving nature by letting the swamp eat the land. The hags direct them. The sap is valuable to alchemists.", "reward": "Black sap worth 5 gp a flask, and a chance to turn the druids against the hags." }, { "n": 66, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Blightcreep", "title": "The Burning Mire", "hear": "\"A yellow haze lies over the bog, bubbles pop, and little flames flicker and die. Your head swims. Nobody who goes in comes out sober.\" A scout lost a day.", "truth": "0714 (14 hexes). Swamp gas ignites in will-o'-wisp flames and causes hallucinations. A dry hummock in the middle holds a hag's cache.", "reward": "A hag's cache worth 100 gp, and a headache." }, { "n": 67, "ring": "C", "type": "Quest", "src": "Climber's Rest", "reg": "Blightcreep", "title": "Blugbort's Slugs", "hear": "\"A little goblin wizard crouches in the swamp muck sorting slimy things into a sack. He pays well for toadstools and slugs. Nobody has asked what for.\"", "truth": "1317 (10 hexes). Blugbort, a goblin wizard, brews a potion that cures swamp poison and sells it to the Forgotten Folk. He wants more slugs.", "reward": "A cure worth 80 gp and a wizard's gratitude." }, { "n": 68, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Blightcreep", "title": "Grizella and Her Raft", "hear": "\"An old woman poles a rotting raft through the mist, muttering, her fingers stained green. She does not look surprised to see you.\"", "truth": "0717 (14 hexes). Grizella Mosspeat, a night hag, ferries passengers across the Rootwalks for a small favour. The favours are not small.", "reward": "Safe passage, a debt to a hag, and a curse waiting to be called in." }, { "n": 69, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Blightcreep", "title": "The Weeping Willow", "hear": "\"A willow in the deep swamp weeps blood, they say, and the hags live beneath it. The druids bow when they pass, and the frogs go silent.\" A teamster's cousin swears he heard it humming a lullaby.", "truth": "Beneath the Black Sap Grove (1015, 11 hexes). The Weeping Willow is the hags' root and the seal of their power, and its sap is why the druids obey. A sharp axe and a steady nerve can stop the swamp spreading, but every blow tells the coven.", "reward": "A swamp that stops spreading, 150 gp from the Warden, and three hags who will remember your faces." }, { "n": 70, "ring": "C", "type": "Quest", "src": "The Crucible", "reg": "Blightcreep", "title": "A Bride for the Swamp", "hear": "\"The druids asked for a bride, someone with an honest heart. A hunter's daughter went last month and has not come back. Her father is at the Crucible every night, drinking.\"", "truth": "1015 (11 hexes). The girl was taken to the Black Sap Grove. She is alive but slowly changing, and the druids mean to wed her to the swamp.", "reward": "A father's gratitude (60 gp) and the girl." }, { "n": 71, "ring": "C", "type": "Quest", "src": "Warden's Hall", "reg": "Blightcreep", "title": "The Rotting Leaf's Peace", "hear": "\"A druid came to the gate with a branch of black leaves, asking for the elves. They want to talk, they say. The Warden wants someone to carry the offer.\"", "truth": "1015 (11 hexes). The druids offer peace to the elves to stop the war with the Court, but the hags are scheming. The offer is a trap meant to draw the elves into the swamp.", "reward": "200 gp for carrying it, and the truth for free." }, { "n": 72, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Rotbark", "title": "The Lich Under the Grey Ring", "hear": "\"A ring of grey stones in the west with a grave-dirt smell, a mound where nothing grows, and a hum you feel in your teeth. The Hunt marks it on no map. Something below is awake and listening.\"", "truth": "0206 (19 hexes). A lich's megadungeon, the home of Aethelgard the Red, who is breaking the seals of Rotbark. The Temple believes the Armor of Saint Terragnis lies in a tomb in its deepest vault, past traps and the lich's undead.", "reward": "The Armor of Saint Terragnis (1,200 gp) if you survive, the lich's phylactery vault, and a priest's blessing." }, { "n": 73, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Rotbark", "title": "The Watchtower of Red Moss", "hear": "\"A squat stone tower in crimson moss behind a palisade, red banners flying and chanting at every hour. The air smells of blood and wet leather.\" A hunter who crept close says the river runs red beneath it.", "truth": "0306 (18 hexes). The Cult of the Leech's watchtower, where kidnappers bleed travellers into the Heartblood River. A prisoner in the cellar has seen the Cult's plans for the seals and can name the leader of the next raid.", "reward": "The prisoner's thanks, the Cult's ledger (it names the Cult's spies in Frostholm), and 50 gp from the prisoner's family." }, { "n": 74, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Rotbark", "title": "The River Like Wine", "hear": "\"A river runs deep red, like watered wine, with a coppery smell. The reeds are stained to the waterline. Something upstream splashes and goes quiet.\"", "truth": "0004 (21 hexes). The Heartblood River. Its water carries the Cult's taint to the lake. Something large swims in it.", "reward": "A cure for the taint, and a monster's hide." }, { "n": 75, "ring": "C", "type": "Rumour", "src": "The Beacon Inn", "reg": "Rotbark", "title": "The Glade of Mirrors", "hear": "\"A glade of glistening red vines, and still pools that reflect the sky like black glass. The vines creep nearer when you stop.\" A scout said one pool showed him a man he had killed, waving.", "truth": "0008 (21 hexes). Blood vines bleed wanderers dry, and the pools preserve the reflection of every victim. A reflection will answer one question truthfully if you give it a drop of blood.", "reward": "One true answer from a drowned reflection, and a cursed hand-mirror worth 90 gp that never fogs." }, { "n": 76, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Rotbark", "title": "The Twin Trees", "hear": "\"Two great trees lean together over the path with silk on every limb, and husks of wrapped things dangle overhead. Spiders the size of dogs watch from the shadows.\" The hunters call it the front door.", "truth": "0308 (18 hexes). The Twin Gate. A nest of giant spiders and ettercaps guards the path into the deep forest. The webs shelter cocooned travellers who are still breathing, including a Hunt scout.", "reward": "Silk worth 80 gp, the scout's thanks, and whatever the spiders took from earlier victims." }, { "n": 77, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Rotbark", "title": "The Silent Treant", "hear": "\"Three giant trees on the riverbank, and between them a tall silent figure of bark and moss, its face tilted up as if listening.\"", "truth": "0608 (15 hexes). Yggral the treant stands watch over the river and speaks only when he must. He knows where the river's rot begins.", "reward": "A treant's blessing and a map of the Heartblood's source." }, { "n": 78, "ring": "C", "type": "Quest", "src": "Climber's Rest", "reg": "Rotbark", "title": "The Climber on the Cliff", "hear": "\"A lone figure climbs the cliff above the river with a heavy pack, patting along the cracks as if searching for something lost. Some say it is a ghost.\"", "truth": "0411 (17 hexes). Mirell, a pearl and gold prospector, searches for a vein he lost forty years ago. He pays well for help.", "reward": "A share of the vein and a pearl worth 60 gp." }, { "n": 79, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Rotbark", "title": "The Hunt's Lost Crew", "hear": "\"The Ember Ten rode west in the autumn and never came back. A raven carried their last message: we have found the river. It is alive.\" The Warden keeps their names on the wall.", "truth": "0004 (21 hexes). The Ember Ten were taken by the Cult of the Leech and turned into its soldiers, their cloaks stained red. Their leader, Captain Vessa, still half-remembers who she is.", "reward": "A chance to free them, the Hunt's thanks, and the Ember Ten's saved loot (200 gp) under the tower." }, { "n": 80, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Cinder Peaks", "title": "The Dragon in the Dwarf-City", "hear": "\"A volcano with black glass streaks, broken dwarven arches half-swallowed by the mountain, and a rumble that does not sound like the mountain.\" A raven that flew over it came back singed.", "truth": "0013 (21 hexes). Ignisax the Smoldering lairs in the ruins of a great dwarven city inside the volcano. The blessing Demonskin (immune to fire) is rumoured to be his gift to anyone who brings him something he cannot get himself.", "reward": "A dragon's hoard from the 10+ table, a dwarven oath, and a very short stay." }, { "n": 81, "ring": "C", "type": "Rumour", "src": "The Iron Ward", "reg": "Cinder Peaks", "title": "The Needle Teeth", "hear": "\"Jagged spires of black rock in the ash, small scaled figures marching in formation, crude barricades, and the tap of hammers.\" They do not look at you, a scout says. They look past you at something behind.", "truth": "0015 (21 hexes). Emberscale kobolds in a stone village under Ignisax's rule, wary of anyone not in his livery. They trade iron and secrets for ale and tinder.", "reward": "A kobold alliance, a map of the ash roads, and a safe-conduct token Ignisax's servants will respect." }, { "n": 82, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Cinder Peaks", "title": "The Ash Fall Workshop", "hear": "\"A smoking workshop in the ash, hung with chains and gears and contraptions. Something small explodes and a chorus of tiny voices cheers.\" Whatever they are building, they are very proud of it.", "truth": "0315 (18 hexes). The kobolds' workshop, where their engineers build ever stranger weapons for the dragon's war. Friendly to anyone with gold, and badly in need of a competent adult.", "reward": "A kobold-built gadget (a one-use grapnel gun or smoke cannon) and a favour from the engineers." }, { "n": 83, "ring": "C", "type": "Rumour", "src": "The Iron Ward", "reg": "Cinder Peaks", "title": "The Glass Maze", "hear": "\"A slope of black glass chimes underfoot, with a stone arch marking a maze, small scaled sentries on the rocks, and a slow heavy snort from within.\" Nobody who goes in has come back with their boots.", "truth": "0413 (17 hexes). The Emberglass Scree maze, guarded by a minotaur (level 4) and kobold sentries. A dragon's pensioned bodyguard sleeps at its centre with a hoard of obsidian relics.", "reward": "A minotaur's horn worth 50 gp, and a chest of obsidian relics worth 150 gp." }, { "n": 84, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Cinder Peaks", "title": "The Scream in the Dunes", "hear": "\"A scream from the caves above the dunes, raw and furious and far too big to be human. Bones and broken things at the cave mouth.\"", "truth": "0418 (17 hexes). A cyclops guards the Booming Dunes. It is lonely and hurt.", "reward": "A cyclops's friendship, and a trove from its bone pile." }, { "n": 85, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Cinder Peaks", "title": "The Sleepers' Rim", "hear": "\"Ruined walls and fallen arches hang from a cliff above a ravine, half-swallowed by moss. A cold draft breathes from the caves, smelling of wet stone and very old things.\" The southern dwarves say not to knock.", "truth": "0117 (20 hexes). Sleepers' Rim. The dwarves' dead sleep in the caves in ranks, and a sealed gate to Deephome lies beneath. Wake the wrong one and the whole rank wakes.", "reward": "A dwarven tomb's treasure (7-9 table), and the gratitude of a ghost who wants her ring buried with her sisters." }, { "n": 86, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Cinder Peaks", "title": "The Visitors from Below", "hear": "\"Drow and duergar in the caves of the south-west, scorched and scraped smooth, with boot prints and drag marks, murmuring in low harsh voices.\" A kobold said they were nice, which is the worst thing anyone has said about them.", "truth": "0210 (19 hexes). The Gloomborn of Deephome, on a surface expedition to hunt dangerous creatures and steal resources. They are neutral to the Hunt and curious about Frostholm.", "reward": "An alliance with the Gloomborn, their map of Deephome, or a secret: the weakness of a surface lord." }, { "n": 87, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Cinder Peaks", "title": "The Drill Ground", "hear": "\"Kobolds in the south-west are drilling like soldiers, in formation, with banners. Somebody is training them for a war,\" and the Warden is quiet about it.", "truth": "0314 (18 hexes). The Ashbite kobolds, under a drillmaster in Ignisax's pay, are preparing a march on the Basin. They would need a guide who knows the lake road.", "reward": "200 gp from the Warden for scouting the force's size, and a chance to sow doubt among the clans." }, { "n": 88, "ring": "C", "type": "Rumour", "src": "The Iron Ward", "reg": "Cinder Peaks", "title": "The Two Clans", "hear": "\"The two kobold clans hate each other more than they hate us. One day they will start a war,\" the old hands say, \"and we will get to watch.\"", "truth": "0215 (19 hexes) and 0015 (21 hexes). The Ashbite and Emberscale clans, both serving Ignisax, feud over a stolen stone idol. A clever party could tip the balance, or broker a truce that makes them stronger.", "reward": "A clan's trust, the stone idol (worth 100 gp), and a long-term ally or enemy." }, { "n": 89, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Cinder Peaks", "title": "The Door Below the Cellars", "hear": "\"The lowest vault of the Black Cellars goes deeper than any floor plan shows. A drow came up from it once and went back down.\" The cellar-keeper's lamp has not stopped trembling since.", "truth": "Beneath Frostholm. A passage to Deephome, the underdark beneath the Wilds, where the Gloomborn live. It emerges at Thunder Shelf, 0210 (19 hexes), and at other places the Gloomborn use.", "reward": "A tunnel under the whole Wilds, a head start on any journey west, and the Gloomborn's curiosity." }, { "n": 90, "ring": "C", "type": "Quest", "src": "The Crucible", "reg": "Behemoth's Rift", "title": "The Hole in the World", "hear": "\"The ground just ends in the far west. A crater miles across and four hundred feet deep, full of green jungle and the bellow of something enormous.\" Nobody can say how far down it goes.", "truth": "0211 (19 hexes). Behemoth's Rift. A jungle of dinosaurs, bounded by cliffs. The Forgotten Folk live along the rim and know the ladders down.", "reward": "Dinosaur eggs and bones worth 100 gp, a ride on a thunder beast, and a story no one will believe." }, { "n": 91, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Behemoth's Rift", "title": "The Bone Salvagers", "hear": "\"People live at the edge of the crater and salvage bones from the beasts that fall in. They are small, quiet, and wary of strangers.\" They tell stories of a time before the Hunt.", "truth": "0211 (19 hexes). The Forgotten Folk know the old stories and trade bones for iron. They revere the crater as a grave and will bargain if you respect it.", "reward": "A Forgotten Folk map of the Rift, a bone charm worth 40 gp, and an elder's tale of the Wilds before the Hunt." }, { "n": 92, "ring": "C", "type": "Quest", "src": "The Crucible", "reg": "Behemoth's Rift", "title": "The Egg Thief", "hear": "\"A man at the Crucible swears he saw an egg the size of a barrel in the far west. A noble in the east will pay a fortune for one.\" The noble's agent keeps leaving coin in a cup.", "truth": "0211 (19 hexes). A dinosaur nest on a ledge below the rim, guarded by a mother tyrannosaur who returns at dusk. Taking an egg is possible, and carrying it out is the hard part.", "reward": "400 gp from the noble, or a rare dinosaur chick worth far more." }, { "n": 93, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Behemoth's Rift", "title": "The Thunder Beasts", "hear": "\"Beasts that shake the ground when they walk, so big a man can ride on a single claw. The Forgotten Folk call them thunder.\"", "truth": "0211 (19 hexes). The crater's dinosaurs, including a brachiosaurus. The Forgotten Folk ride the gentler ones, and a tame one can be borrowed for the climb down.", "reward": "A shed dinosaur tooth worth 50 gp, and a ride on a thunder beast's back if the Forgotten Folk allow it." }, { "n": 94, "ring": "C", "type": "Quest", "src": "The Crucible", "reg": "Rimewastes", "title": "The Dwarf Lord's Trackers", "hear": "\"A band of duergar stumbles through the northern snow, sun-dazzled and half blind, running from a Dwarf Lord's trackers. They beg any stranger for help.\"", "truth": "The far north. The duergar are Gloomborn thieves who stole from the Dwarf Lord's mithral dig at the Cloven Boulder (0514, 16 hexes). His trackers are honest dwarves with a real grievance. Both sides want the party's word.", "reward": "The stolen mithral (100 gp), or the Dwarf Lord's oath: a dwarven forgemaster will make you a spectacular sword." }, { "n": 95, "ring": "C", "type": "Quest", "src": "The Crucible", "reg": "Rimewastes", "title": "The Ten-Eyed Oracle", "hear": "\"A thing drifts in the northern dark, chattering of doom, with ten eyes that never blink. It knows everything. It asks only for a price.\"", "truth": "Anywhere in the far north. The Ten-Eyed Oracle is a creature of the void and drifts wherever doom is gathering. It answers one question honestly and one falsely, and will not say which.", "reward": "One true prophecy about your next fight, and one false one." }, { "n": 96, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Golden Waves", "title": "The Alabaster Library", "hear": "\"A white library appears in the wheat once a season at dawn, doors open, and by noon it is gone. The scholar who went in last year has been seen in three towns since.\"", "truth": "Anywhere in the Golden Waves. The legendary Alabaster Library of Gehemna materialises for a day. Its stacks hold lost lore, including the Sphinx's riddles.", "reward": "A tome worth 200 gp and a riddle's answer." }, { "n": 97, "ring": "C", "type": "Rumour", "src": "The Black Cellars", "reg": "Winter's Edge", "title": "The Armor of Saint Terragnis", "hear": "\"The Temple of the Last Hearth keeps an empty niche where the Armor of Saint Terragnis once hung. The priests say it was carried west by a knight who never returned.\"", "truth": "0206 (19 hexes). The Armor lies in the lich Aethelgard's deepest vault. The priests will pay a fortune and grant a blessing for its return.", "reward": "1,200 gp, the blessing Divine Halo, and a place of honour in the Temple." }, { "n": 98, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Blightcreep", "title": "The Obsidian Witchknife", "hear": "\"A knife of obsidian that cuts what it should not, kept in a hag's jar of black water in the swamp. The hags will trade it, they say, for something precious.\"", "truth": "0916 (12 hexes). The Black-Spit Hag Coven holds the Obsidian Witchknife. They want a child's first word, a king's name, or a lie that has never been told.", "reward": "The Obsidian Witchknife (1,200 gp) and a hag's debt." }, { "n": 99, "ring": "C", "type": "Rumour", "src": "The Crucible", "reg": "Frostholm", "title": "The Hunters' Songbook", "hear": "\"Every Hunt crew has a verse. Sing it right and the Wilds tell you where the water is. Sing it wrong and you are a verse in someone else's song.\"", "truth": "No fixed hex. The old songbook at the Crucible holds a verse for every region, each hiding a true landmark in its rhymes.", "reward": "A hand-drawn map, and a free round for everyone at the Crucible." }, { "n": 100, "ring": "C", "type": "Rumour", "src": "Temple of the Last Hearth", "reg": "Cinder Peaks", "title": "The Shrine of Madeera", "hear": "\"A little shrine in the south-west hills, a stone goddess with a bowl in her hands. Leave an offering and your next throw lands true.\" The Temple's older priests nod, and say nothing more.", "truth": "On the road past the Sleepers' Rim, around 0117 (20 hexes). A real shrine to Madeera. A coin in the bowl grants a luck token, once per traveller. Emberscale kobolds raid it for the offerings, and the shrine's keeper is a lonely hermit.", "reward": "A luck token, a goddess's favour, and a hermit's tale of the dwarves." }];
let hkF = { hp: '', ht: '', hr: '' }, hkOpen = new Set();
const hkList = () => HK.filter(k => (!hkF.hp || k.ring == hkF.hp) && (!hkF.ht || k.type == hkF.ht) && (!hkF.hr || k.reg == hkF.hr));
const hexLinks = t => e(t).replace(/\b(\d{4})\b/g, (m, id) => H[id] ? `<a class="lk" data-go="${id}">${id}</a>` : m);
const hkItem = k => `<details class="hk" id="hk${k.n}" data-n="${k.n}" ${hkOpen.has(k.n) ? 'open' : ''}><summary><b>${k.n}. ${e(k.title)}</b> <span class="mu">${e(k.type)} &middot; ${e(k.src)} &middot; ${e(k.reg)}</span></summary><p class="read">${e(k.hear)}</p><p><b>Truth (GM):</b> ${hexLinks(k.truth)}</p><p><b>Reward:</b> ${hexLinks(k.reward)}</p></details>`;
paint(); render();